const summariseRateChanges = `-- name: SummariseRateChanges :one
SELECT
  count(*)::bigint                                        AS nights,
  count(DISTINCT room_id)::bigint                         AS rooms,
  count(*) FILTER (WHERE old_price IS NULL)::bigint       AS nights_gaining_a_price,
  count(*) FILTER (WHERE new_price IS NULL)::bigint       AS nights_losing_their_price,
  min(night)::date                                        AS first_night,
  max(night)::date                                        AS last_night
FROM rate_calendar_changes($1, $2)
`

type SummariseRateChangesParams struct {
	FromDate pgtype.Date
	ToDate   pgtype.Date
}

type SummariseRateChangesRow struct {
	Nights                 int64
	Rooms                  int64
	NightsGainingAPrice    int64
	NightsLosingTheirPrice int64
	FirstNight             pgtype.Date
	LastNight              pgtype.Date
}

// What saving would change, summarised (decision #21's "diff before saving").
//
// Called inside the transaction that has already applied the edit and is about
// to roll back, so it compares the live calendar against what the edited
// seasons would generate. Aggregated rather than listed: the owner needs to
// know it is 142 nights and not 14,000, and a per-night list is a screen nobody
// reads.
func (q *Queries) SummariseRateChanges(ctx context.Context, arg SummariseRateChangesParams) (SummariseRateChangesRow, error) {
	row := q.db.QueryRow(ctx, summariseRateChanges, arg.FromDate, arg.ToDate)
	var i SummariseRateChangesRow
	err := row.Scan(
		&i.Nights,
		&i.Rooms,
		&i.NightsGainingAPrice,
		&i.NightsLosingTheirPrice,
		&i.FirstNight,
		&i.LastNight,
	)
	return i, err
}

