// The owner's console (build-order step 6).
//
// Read models rather than a general query surface: each of these answers one
// screen's question in one round trip, because the console is used one-handed
// on a phone on a bad connection and a screen that needs five queries to draw
// itself is a screen that half-draws.
//
// Money is integer cents here as everywhere. The two rates cross the boundary
// pre-scaled to hundred-thousandths so no numeric is ever decoded into a float.
// ---------------------------------------------------------------------------
// Today, and the booking list
// ---------------------------------------------------------------------------
// Everything happening at the inn on one day (decision: the console's first
// screen).
//
// One query and one bucket column rather than three round trips, because the
// three questions share a row shape and the answer to all of them is "the
// confirmed stays that touch this date". checkin <= on <= checkout catches all
// three: an arrival is a stay whose check-in is today, a departure one whose
// checkout is today, and everything between is in-house. They cannot overlap —
// a booking with checkin = checkout is refused by a CHECK constraint.
//
// Confirmed only. A pending booking is an unpaid hold in somebody's browser,
// and putting it on the arrivals board would have the owner making up a bed for
// a guest who never paid.
func (q *Queries) TodayBoard(ctx context.Context, onDate pgtype.Date) ([]TodayBoardRow, error) {
	rows, err := q.db.Query(ctx, todayBoard, onDate)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TodayBoardRow{}
	for rows.Next() {
		var i TodayBoardRow
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.Checkin,
			&i.Checkout,
			&i.Guests,
			&i.WithPet,
			&i.TotalCents,
			&i.AmountPaidCents,
			&i.BalanceChargeAt,
			&i.BalanceChargeFailedAt,
			&i.GuestName,
			&i.GuestEmail,
			&i.GuestPhone,
			&i.RoomNames,
			&i.Bucket,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateRateSeason = `-- name: UpdateRateSeason :execrows
UPDATE rate_seasons SET
  name       = $1,
  starts_on  = $2,
  ends_on    = $3,
  min_stay   = $4,
  priority   = $5,
  updated_at = now()
WHERE id = $6
`

type UpdateRateSeasonParams struct {
	Name     string
	StartsOn pgtype.Date
	EndsOn   pgtype.Date
	MinStay  *int32
	Priority int32
	ID       int64
}

func (q *Queries) UpdateRateSeason(ctx context.Context, arg UpdateRateSeasonParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateRateSeason,
		arg.Name,
		arg.StartsOn,
		arg.EndsOn,
		arg.MinStay,
		arg.Priority,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateRoom = `-- name: UpdateRoom :execrows
UPDATE rooms SET
  name                   = $1,
  description            = $2,
  view                   = $3,
  max_occupancy          = $4,
  amenities              = $5,
  is_accessible          = $6,
  accessibility_features = $7,
  is_pet_friendly        = $8,
  pet_fee_cents          = $9,
  sort_order             = $10,
  updated_at             = now()
WHERE id = $11
`

type UpdateRoomParams struct {
	Name                  string
	Description           string
	View                  *string
	MaxOccupancy          int32
	Amenities             []string
	IsAccessible          bool
	AccessibilityFeatures []string
	IsPetFriendly         bool
	PetFeeCents           int32
	SortOrder             int32
	ID                    int64
}

// The accessibility honesty rule (decision #22) is a CHECK constraint on the
// table, so this cannot set the flag without features and does not re-check it
// here: enforcing it in whichever statement happens to write the row is exactly
// the arrangement that constraint exists to replace.
func (q *Queries) UpdateRoom(ctx context.Context, arg UpdateRoomParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateRoom,
		arg.Name,
		arg.Description,
		arg.View,
		arg.MaxOccupancy,
		arg.Amenities,
		arg.IsAccessible,
		arg.AccessibilityFeatures,
		arg.IsPetFriendly,
		arg.PetFeeCents,
		arg.SortOrder,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateSettings = `-- name: UpdateSettings :exec

UPDATE settings SET
  default_min_stay       = $1,
  max_stay_nights        = $2,
  tax_rate               = $3::bigint::numeric / 100000,
  refund_processing_rate = $4::bigint::numeric / 100000,
  hold_ttl_minutes       = $5,
  payment_grace_minutes  = $6,
  checkin_time           = $7,
  checkout_time          = $8,
  accessibility_notice   = $9,
  updated_at             = now()
WHERE id
`

type UpdateSettingsParams struct {
	DefaultMinStay             int32
	MaxStayNights              int32
	TaxRateScaled              int64
	RefundProcessingRateScaled int64
	HoldTtlMinutes             int32
	PaymentGraceMinutes        int32
	CheckinTime                pgtype.Time
	CheckoutTime               pgtype.Time
	AccessibilityNotice        string
}

// ---------------------------------------------------------------------------
// Settings
// ---------------------------------------------------------------------------
// Both rates arrive pre-scaled to hundred-thousandths and are divided back in
// SQL, mirroring GetSettings exactly. The CHECK constraints on the table are
// what refuse a nonsense value, so a bad save is a database error rather than a
// silently accepted 850% tax rate.
func (q *Queries) UpdateSettings(ctx context.Context, arg UpdateSettingsParams) error {
	_, err := q.db.Exec(ctx, updateSettings,
		arg.DefaultMinStay,
		arg.MaxStayNights,
		arg.TaxRateScaled,
		arg.RefundProcessingRateScaled,
		arg.HoldTtlMinutes,
		arg.PaymentGraceMinutes,
		arg.CheckinTime,
		arg.CheckoutTime,
		arg.AccessibilityNotice,
	)
	return err
}

const upsertPageCopy = `-- name: UpsertPageCopy :exec
INSERT INTO page_copy (slug, heading, body)
VALUES ($1, $2, $3)
ON CONFLICT (slug) DO UPDATE
SET heading    = excluded.heading,
    body       = excluded.body,
    updated_at = now()
`

type UpsertPageCopyParams struct {
	Slug    string
	Heading string
	Body    string
}

func (q *Queries) UpsertPageCopy(ctx context.Context, arg UpsertPageCopyParams) error {
	_, err := q.db.Exec(ctx, upsertPageCopy, arg.Slug, arg.Heading, arg.Body)
	return err
}
